  const h=e=>{const d=e.data;if(!f||e.source!==f.contentWindow||!d||d.k!=='py')return;
    if(d.t==='hello'){ready=true;q.splice(0).forEach(m=>f.contentWindow.postMessage(m,'*'));return}onMsg(d)};
