    if(m.t==='ready'){if(!busy)st.textContent='✅ Python готовий до запуску';return}
    if(m.t==='append'){const tn=document.createTextNode(String(m.m));if(inpEl&&inpEl.parentNode===pre)pre.insertBefore(tn,inpEl);else pre.appendChild(tn);pre.scrollTop=pre.scrollHeight;clearTimeout(onMsg._t);onMsg._t=setTimeout(()=>{if(o.onDone)o.onDone({out:pre.textContent})},1500);return}
    if(m.t==='gui'){if(!busy&&m.on===false&&st.textContent.indexOf('🖼')===0)st.textContent='🖼 Вікно програми закрито';return}
    if(m.t==='fatal'){if(m.id!==undefined&&m.id!==rid)return;busy=false;st.textContent='❌ Не вдалося запустити Python: '+(/loadPyodide|fetch|Network|load/i.test(m.m)?'його не вдалося завантажити з cdn.jsdelivr.net — перевірте інтернет і доступ до цього сайту':m.m);return}
